package keystrokesmod.script.model;
import java.io.BufferedReader; import java.io.InputStream; import java.io.InputStreamReader; import java.net.HttpURLConnection; import java.net.URL; import java.nio.charset.StandardCharsets; import java.util.ArrayList; import java.util.LinkedHashMap; import java.util.List; import java.util.Map;
/** Explicit opt-in HTTP helper retained for Raven scripts. Network activity is initiated only by the script. */
public class Request { private final String method,url; private final Map<String,String> headers=new LinkedHashMap<String,String>(); private String content=""; private int connectTimeout=8000,readTimeout=8000; public Request(String method,String url){this.method=method;this.url=url;} public void addHeader(String key,String value){headers.put(key,value);} public void setUserAgent(String value){addHeader("User-Agent",value);} public void setConnectTimeout(int value){connectTimeout=Math.max(0,value);} public void setReadTimeout(int value){readTimeout=Math.max(0,value);} public void setContent(String value){content=value==null?"":value;} public Response fetch(){try{HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setRequestMethod(method);connection.setConnectTimeout(connectTimeout);connection.setReadTimeout(readTimeout);for(Map.Entry<String,String> entry:headers.entrySet())connection.setRequestProperty(entry.getKey(),entry.getValue());if(!content.isEmpty()){connection.setDoOutput(true);connection.getOutputStream().write(content.getBytes(StandardCharsets.UTF_8));}int code=connection.getResponseCode();InputStream stream=code>=400?connection.getErrorStream():connection.getInputStream();StringBuilder result=new StringBuilder();if(stream!=null){BufferedReader reader=new BufferedReader(new InputStreamReader(stream,StandardCharsets.UTF_8));String line;while((line=reader.readLine())!=null)result.append(line).append('\n');reader.close();}List<String[]> values=new ArrayList<String[]>();for(Map.Entry<String,List<String>> entry:connection.getHeaderFields().entrySet())if(entry.getKey()!=null)values.add(new String[]{entry.getKey(),String.valueOf(entry.getValue())});return new Response(code,result.toString(),values);}catch(Exception exception){return new Response(-1,exception.getMessage());}} @Override public String toString(){return method+" "+url;} }
